update public.ai_products set facts = facts || jsonb_build_object(
    'look', 'دولاب واحد بس فوق الحوض: صندوق مقفول للأطباق بدلفة أكريليك (شكلها زي الزجاج المضلع) بتتفتح لفوق، وفوق الدولاب سطح مفتوح بيتحط عليه البرطمانات والبهارات، وتحته الحوض مكشوف وعلى الجناب حامل سكاكين ولوح التقطيع ومكان للمناديل ورف صغير لأدوات الغسيل. ده الشكل اللي في صور كارته وفي إعلاناته. ناس كتير بتسميه «دورين» عشان فيه الدولاب وتحته رف، بس اللي بيفرّقه عن الدورين إن فيه دولاب واحد بس.',
    'front', 'دلفة أكريليك (مش زجاج) بتتفتح لفوق'), updated_at = now()
where id = 'f8f1f7fc-0b73-4dcf-8e88-9d74044f9994' and tenant_id = '9c58b214-f11d-4de5-afc7-a0de0b903f36';

update public.ai_products set facts = facts || jsonb_build_object(
    'look', 'دولابين مقفولين فوق بعض (صندوقين، واحد فوق التاني) كل واحد بدلفة أكريليك شفافة، وتحتهم الحوض مكشوف. ده الفرق اللي بيبان في الصورة عن الدور الواحد (اللي فيه دولاب واحد بس وفوقه سطح مفتوح) — الدلفة الأكريليك موجودة في الاتنين.'), updated_at = now()
where id = '83d06fd8-bd60-486f-a987-97e4c81a6154' and tenant_id = '9c58b214-f11d-4de5-afc7-a0de0b903f36';
